  dsKneeN: 100, dsKneeG: 95, dsGradePow: 0.8, dsGradeMax: 125, dsTailPow: 1, dsHp: 3.3, dsAtk: 1.6, dsWound: 0.7, dsTitanHp: 0.35, dsTitanAtk: 1.0, dsDanger: 1.2, dsEliteHp: 1.4, dsEliteAtk: 1.15,   // Спуск в Тартар: tools/descent/sim.mjs (16.10.2026: dsHp 3→3,3, dsAtk 1,3→1,6 — глубина как до Пантеона v2)
  trialEndX: 1.94,                     // см. trialFoe — множитель здоровья и урона последних чудищ (подбор tools/bal/final90.mjs: финальный этап — ≈10% побед полной прокачки)
  trialHp: 4.5, trialAtk: 2.2,      // здоровье чудовищ растёт от ×1 (первое) до ×trialHp (50-е) — у них нет супер-ударов и существ; подбор: tools/trial.mjs
                                    // (отряд, где всё XX★5, проходит все 50 в ≈65%; всё 90 — доходит до ≈44-го; новичок убивает 1–4)
  trialRage: [0.01, 0.03, 0.10], trialRageN: 10, trialRageTail: 0.5, trialRageEvery: 5,   // ярость Испытаний: каждые 5 с боя урон чудищ растёт — первые 10 раз на 1%, следующие 10 на 3%, ещё 10 на 10%, дальше на 50% до конца боя (было 25%) (проценты складываются)
  trialRage2: [30, 5, 60, 15, 10, 10],   // 161 (Максим 09.11): ярость Испытаний — первые 30 с роста нет; на 30-й с сразу +500%; на 60-й ещё +1500%; дальше каждые 10 с ещё +1000% (бои, начатые до обновления, — по trialRage выше)
  trialWound: 0.35,                 // раны героев, как в Завоевании: иначе танк с лекарем стоят вечно против слабых волн
