/* Версия правил боя. Записи боёв (турниры, Гранд-арена, Колизей) пересчитываются из seed.
   При правке порядка случайностей или баланса версию повышают; записи другой версии не пересчитываются новыми правилами. */
const SIM_V = 46; // 46: 167g feeding steps grow (crFeedStats). Progression profiles150; clock43/44 and legacy active battles remain supported.

// 149: отсутствие версии означает прежние правила43, включая старые журналы экономики.
function battleClockSupported(cv) { return cv == null || cv === 43 || cv === 44; }
function battleClockRecord(record, cv) { if (cv === 44) record.cv = 44; return record; }
function battleClock(b, cv) {
  if (cv === 44) { b.cv = 44; b.clockTick = 0; }
  return b;
}
function battleClockStep(b, dt) {
  if (b.cv === 44) {
    if (dt !== 0.05) throw new Error('battle_clock_fixed_step');
    b.clockTick++; b.t = b.clockTick / 20;
  } else b.t += dt;
}

// Детерминированность расчёта: степени и экспоненты используют dpow/dexp с одинаковым результатом на всех движках.
/* ============================================================
   СИМУЛЯЦИЯ — чистая логика без DOM. Этот же код гоняет бот баланса (tools/).
   ============================================================ */
/* CONFIG — в таблице баланса (src/sim/core/balance.js) */

