const EX_SRC = { vip: 'VIP', trial: 'Испытания', arena: 'Арена богов', war: 'Завоевание', ach: 'Трофеи', tw: 'Стихийные башни', dg: 'Подземелье — звёзды' };
const exSrcOf = o => o ? (o.vip ? 'vip' : o.ex || '') : '';
const exOnly = o => { const k = exSrcOf(o); return k ? 'только ' + EX_SRC[k] : ''; };
/* звуки ударов: у новых богов своих пока нет (Ludo позже) — берут звук похожего бога (поле sfx) */
