function teamPowAt(g) { const sk = 1 + CONFIG.skillStep * (g - 1); return Math.round(CONFIG.teamSize * 100 * gradeMult(g) * hpGradeBonus(g) * (1 + 0.35 * (sk - 1) + 0.25 * (sk - 1))); }
