  const cur = combatQS(S.skills && S.skills[id] && S.skills[id][k]);
  if (own && gradeOf(c) <= gradeOf(cur)) return 0;
  const sk0 = Object.assign({ a: { q: 1, stars: 1 }, s: { q: 1, stars: 1 }, h: { q: 1, stars: 1 } }, own && S.skills && S.skills[id] || {});
  const at = sk => combatGodPower(combatProfileS(Object.assign({}, S, { codex: { [id]: h }, skills: Object.assign({}, S.skills, { [id]: sk }) }), [h], { higher: false }), id);
