  const name = p.name;
  if (!nickShape(name) || /^\p{L}{2}[ _-]?\d+$/u.test(name)) return { err: 'Недопустимый ник' };
  if (name === S.nkName || name === (S.profile && S.profile.name)) return { cost: 0, name, unchanged: 1 };
  const n = S.nkN | 0, cost = n >= 1 ? NICK_COST : 0, gift = n === 0 ? NICK_GIFT : 0;   // 161 п.7: первая смена — бесплатно и награда NICK_GIFT (счётчик nkN — один раз навсегда)
  if (cost && !((S.gems || 0) >= cost)) return { err: 'Не хватает алмазов' };
  if (cost) S.gems -= cost;
  if (gift) S.gems = (S.gems || 0) + gift;
