  if (!EX_ELS.includes(el) || !pack) return { err: 'Нет такого набора' };
  if (!((S.gems || 0) >= pack.gems)) return { err: 'Не хватает алмазов' };
  const quoteErr=gemSpendError(S,'stoneEl',p,X.now);if(quoteErr)return quoteErr;
  S.gems -= pack.gems;
