  if (!trpTaskReady(S, task)) return { err: 'Задание ещё не выполнено' };
  const R = S.rc || (S.rc = { c: {}, m: {}, n: 0 }); if (!R.c) R.c = {}; if (!R.m) R.m = {};
  const r = X.rng('trp' + v.t + '|' + key), out = rcGrantS(S, rcRoll(S, r, lgDay(X.now)), r, X.now);   // призыв Астрала уровня игрока (было — уровень = номер трофея)
