  if (!g) return null; const q = Math.ceil(g / 5), st = g - (q - 1) * 5;
  return { k: 'hg', id: any ? HG_POOL[(h >>> 0) % HG_POOL.length].id : v34Pick(HG_IDS_V34, (h >>> 0) % HG_IDS_V34.length), q, stars: st, v: hgPrice(q, st) };
