/* Стихийные башни (19.10.2026). Модуль расчёта (128): src/sim/modes/towers.js, место в склейке — src/manifest.json.
   Числа, которых не было в задании, собраны в TW. Бой не меняется, пока у игрока нет реликвии башни;
   пять богов с ex:'tw' уходят из HERO_IDS — это меняет состав врагов, поэтому при вставке нужен SIM_V + 1. */
/* TW — в таблице баланса (src/sim/core/balance.js) */
function twEl(day) {
  const i = ((day - TW.d0) % TW.order.length + TW.order.length) % TW.order.length;
  return TW.order[i];
}
function twReq(L) {
  const x = L | 0;
  for (let i = 0; i < TW.bands.length; i++) if (x >= TW.bands[i].from && x <= TW.bands[i].to) return TW.bands[i];
  return null;
}
function twGrade(L) {
  const x = Math.max(1, Math.min(TW.levels, L | 0));
  return Math.max(1, Math.min(100, Math.round(1 + (x - 1) * 99 / (TW.levels - 1)) + (TW.gBias | 0)));
}
function twGemsOf(L) {
  const x = Math.max(1, Math.min(TW.levels, L | 0));
  return Math.max(TW.gemMin, Math.round(TW.gemTop * dpow(x / TW.levels, TW.gemPow)));
}
