/*SD:sim*/
/* === 7 дней входа ===
   Акция у всех, постоянная. 7 наград по кругу. В сутки МСК (lgDay) — одна, всегда следующая по счёту.
   Пропуск сутки не сбрасывает круг. Седьмую забрали — со следующих суток круг снова с первой.
   Качество сундука и ульты — от алтаря в момент забора. Числа ниже — предложение (в задании их не было).
   Ценность: 1 призыв = SD.soul 💎, SD.gold золота = 1 💎, сундук = uchVal, ульта = lgVal ступени × SD.soul.
   S.sd = {n: забрано в круге 0…6, r: номер круга, d: сутки последнего забора}. */
/* SD — в таблице баланса (src/sim/core/balance.js) */
function sdSt(S) {
  const o = S && S.sd, on = !!(o && typeof o === 'object');
  let n = 0, r = 0, d = 0;
  if (on) { n = o.n | 0; r = o.r | 0; d = o.d | 0; }
  if (n < 0) n = 0;
  if (n > 6) n = 6;
  if (r < 0) r = 0;
  return { n, r, d, on };
}
function sdQ(S) {
  let q = (S && S.altar) | 0;
  if (q < 1) q = 1;
  if (q > CONFIG.altarMaxLevel) q = CONFIG.altarMaxLevel;
  return q;
}
function sdQAt(q, plus) {
  let x = (q | 0) + (plus | 0);
  if (x < 1) x = 1;
  if (x > CONFIG.altarMaxLevel) x = CONFIG.altarMaxLevel;
  return x;
}
/* бог ульты круга: один и тот же, пока круг не сменился. Ключ — номер круга, не сутки и не алтарь */
function sdHero(S, r) {
  const seed = (S && S.eco && S.eco.seed) >>> 0;
  const rng = mulberry(ecoKey(seed, 'sd' + (r | 0) + ':7'));
  return v34Pick(HERO_IDS_V34, Math.floor(rng() * HERO_IDS_V34.length));   // список v34, Исида — следующий бог
}
/* неделя «7 дней входа» стоит не больше SD_MAX 💎 (на алтаре XX), на I — SD_MIN; доли дней — SD_SH.
   Сундук и ульта — лучшее качество, которое укладывается в долю дня (по lgVal / uchVal), остаток — алмазами. */
/* SD_MAX, SD_MIN, SD_SH — в таблице баланса (src/sim/core/balance.js) */
const sdWeek = q => Math.round(SD_MIN + (SD_MAX - SD_MIN) * dpow((q - 1) / 19, 1.6));
/* SD_SOULS, SD_D7, SD_PICK — в таблице баланса (src/sim/core/balance.js) */
function sdRewards(S, circle) {
  const r = circle | 0, out = [];
  for (let i = 0; i < 6; i++) out.push({ d: i + 1, items: [{ k: 'souls', n: SD_SOULS[i] }] });
  out.push({ d: 7, items: [{ k: 'souls', n: SD_D7 }] });   // и в первом круге (r = 0) — сферы
  return out;
}
function sdItemVal(it) {
  if (!it) return 0;
  if (it.k === 'gems') return it.n;
  if (it.k === 'gold') return it.n / SD.gold;
  if (it.k === 'souls') return it.n * SD.soul;
  if (it.k === 'uch') return uchVal(it.q);
  const g = ((it.q | 0) - 1) * 5 + ((it.stars | 0) || 1);
  return lgVal(g) * SD.soul;
}
function sdDayVal(day) {
  let s = 0;
  for (const it of day.items) s += sdItemVal(it);
  return Math.round(s);
}
/* вид без изменений S: следующая награда, можно ли сегодня, мс до полуночи МСК, все 7 наград под текущий алтарь */
function sdView(S, now) {
  const st = sdSt(S), day = lgDay(now), rw = sdRewards(S, st.r);
  const days = [];
  let sum = 0;
  for (const x of rw) { const v = sdDayVal(x); sum += v; days.push({ d: x.d, items: x.items, v }); }
  return {
    n: st.n, r: st.r, d: st.d, altar: sdQ(S), day,
    next: st.n + 1, can: !st.on || day > st.d, left: lgEnd(day) - now,
    rw: days, sum,
  };
}
ECO_TX.sdTake = (S, p, X) => {
  const day = lgDay(X.now), st = sdSt(S);
  if (st.on && day <= st.d) return { err: 'Сегодня награда уже получена' };
  const rw = sdRewards(S, st.r)[st.n];
  if (!rw) return { err: 'Нет награды' };
  for (const it of rw.items) {
    if (it.k === 'pick' && !(isHeroId(p.id) && HERO_IDS.includes(p.id))) return { err: 'Выберите бога' };   // бог на выбор — только из богов алтаря
    if (it.k === 'h' && !isHeroId(it.id)) return { err: 'Нет награды' };
    if ((it.k === 'gems' || it.k === 'gold' || it.k === 'souls') && !((it.n | 0) > 0)) return { err: 'Нет награды' };
    if (it.k === 'uch' && !(it.q >= 1 && it.q <= CONFIG.altarMaxLevel)) return { err: 'Нет награды' };
  }
  const rng = X.rng('sd' + st.r + ':' + (st.n + 1)), got = [];
  for (const it of rw.items) {
    if (it.k === 'uch') { uchAdd(S, it.q, 'sd'); got.push({ k: 'uch', q: it.q }); }
    else if (it.k === 'pick') got.push(grantS(S, { k: 'g', id: p.id, q: it.q, stars: it.stars }, rng, X.now));
    else got.push(grantS(S, it, rng, X.now));
  }
  const n1 = st.n + 1;
  S.sd = n1 >= 7 ? { n: 0, r: st.r + 1, d: day } : { n: n1, r: st.r, d: day };
  return { day: n1, got, r: S.sd.r };
};
/*SD:sim-END*/

/* 153: shared deterministic economy. Presentation consumes confirmed receipts only. */
function monoFresh(now) {
  return {v:1,seq:0,moves:0,rolls:10,dollars:0,pos:0,at:now,regen:0,tiles:Array(40).fill(0),statues:{},active:null,items:{},collections:{},
    totals:{rolls:0,events:0,builds:0},park:0,boosts:{},pending:null,followup:null,receipt:null,seen:null,history:[],
    day:{id:Math.floor(now/MONOPOLY_RULES.dailyMs),rolls:0,events:0,builds:0,income:0,cells:0,base:10,points:0,taken:[]},
    cycle:{id:Math.floor(now/MONOPOLY_RULES.cycleMs),points:0,rolls:0,events:0,builds:0,taken:[]},cosmetics:[],equipped:{},rewardIds:[],inbox:[]};
}
// 153 v5: награды альбома — собрано разных предметов у бога / во всём альбоме
function monoGot(M,id) { return (M.items[id]||[]).reduce((a,x)=>a+(x?1:0),0); }
function monoGotAll(M) { return Object.keys(M.items).reduce((a,id)=>a+monoGot(M,id),0); }
function monoSafe(n) { return Number.isSafeInteger(n)&&n>=0&&n<=MONOPOLY_RULES.maxSafe; }
function monoAdd(a,b) { const n=a+b;if(!monoSafe(n))throw Error('Неверное количество');return n; }
function monoQuality(n) { let q=0;while(q<19&&n>=MONOPOLY_RULES.threshold[q+1])q++;return q; }
function monoIncome(n,m) { let total=0;for(let i=0;i<m;i++)total+=MONOPOLY_RULES.income[monoQuality(n+i)];return total; }
// v7 (Максим 09.11, п. 1 и 15): Казна, Звездопад, Усиление колеса, Погоня, Счастливая монета и «Неожиданный джекпот» убраны.
// Старые сохранения: поля этих механик тихо отбрасываются, незавершённое событие убранного вида снимается (возврата нет — решение для TEST).
const MONO_EVENTS=['bank','megaBank','chance','chest','parking','wheel','harvest','rain'];
function monoMigrate(M) {
  if(!M||typeof M!=='object')return M;
  for(const k of ['tickets','coins','chase','pegCount'])delete M[k];
  if(M.boosts&&typeof M.boosts==='object')delete M.boosts.wheelBoost;
  const gone=e=>e&&typeof e==='object'&&['coin','megaCoin','jackpot','peg'].includes(e.type);   // только убранные виды; незнакомый вид по-прежнему — повреждение
  if(gone(M.followup))M.followup=null;
  if(gone(M.pending)){M.pending=M.followup||null;M.followup=null;}
  if(M.receipt&&typeof M.receipt==='object'){delete M.receipt.tickets;delete M.receipt.chaseCaught;}
  return M;
}
function monoCheck(M) {
  if(!M||M.v!==1||!monoSafe(M.seq)||!monoSafe(M.rolls)||!monoSafe(M.dollars)||!pInt(M.pos,0,39)||!monoSafe(M.at)||!monoSafe(M.regen))return false;
  if(!Array.isArray(M.tiles)||M.tiles.length!==40||!M.tiles.every(monoSafe))return false;
  if(!M.statues||!M.items||!M.collections||!M.totals||!M.boosts||!M.day||!M.cycle||!Array.isArray(M.history)||!Array.isArray(M.cosmetics))return false;
  if(M.active!==null&&!ALL_HERO_IDS.includes(M.active))return false;
  for(const id of Object.keys(M.statues))if(!ALL_HERO_IDS.includes(id)||!pInt(M.statues[id],0,10))return false;
  if(Object.entries(M.statues).some(([id,n])=>n>0&&n<10&&id!==M.active)||M.active&&M.statues[M.active]===10)return false;
  for(const id of Object.keys(M.items))if(!ALL_HERO_IDS.includes(id)||!Array.isArray(M.items[id])||M.items[id].length!==20||!M.items[id].every(x=>x===0||x===1))return false;
  for(const id of Object.keys(M.collections))if(!ALL_HERO_IDS.includes(id)||M.collections[id]!==1||!M.items[id]||!M.items[id].every(Boolean))return false;
  if(Object.entries(M.items).some(([id,row])=>row.every(Boolean)&&M.collections[id]!==1))return false;
  if(M.rolls>=10?M.regen!==0:!(M.regen>M.at))return false;
  const unique=(a,test)=>Array.isArray(a)&&a.every(test)&&new Set(a).size===a.length;
  if(!['id','rolls','events','builds','income','cells','points'].every(k=>monoSafe(M.day[k]))||!Number.isFinite(M.day.base)||M.day.base<10||!unique(M.day.taken,n=>pInt(n,0,2)))return false;
  if(!['id','points','rolls','events','builds'].every(k=>monoSafe(M.cycle[k]))||!unique(M.cycle.taken,n=>pInt(n,0,19)))return false;
  if(Object.entries(M.boosts).some(([k,n])=>!MONOPOLY_RULES.boostOrder.includes(k)||!monoSafe(n)))return false;
  if(M.alb!==undefined){const A=M.alb,B=MONOPOLY_RULES;if(!A||!unique(A.t,n=>pInt(n,0,B.albumSteps.length-1))||!A.c||typeof A.c!=='object'||Array.isArray(A.c))return false;
    for(const [id,row] of Object.entries(A.c))if(!ALL_HERO_IDS.includes(id)||!unique(row,n=>pInt(n,0,B.colSteps.length-1))||row.some(n=>monoGot(M,id)<B.colSteps[n]))return false;
    if(A.t.some(n=>monoGotAll(M)<B.albumSteps[n]))return false;}
  if(!unique(M.rewardIds,k=>typeof k==='string'&&k.length>0&&k.length<=160)||!Array.isArray(M.inbox))return false;
  const receipt=r=>r&&typeof r.id==='string'&&monoSafe(r.step)&&monoSafe(r.next)&&Array.isArray(r.items)&&Array.isArray(r.completed);
  if(M.receipt!==null&&!receipt(M.receipt)||!M.inbox.every(receipt))return false;
  if(M.history.length>16||!M.history.every(h=>h&&typeof h.id==='string'&&typeof h.signature==='string'&&receipt(h.result)))return false;
  const cosmetics=['avatar:monopoly-laurel','icon:monopoly-dollar','token:monopoly-obelisk'];
  if(!unique(M.cosmetics,k=>cosmetics.includes(k))||!M.equipped||Object.entries(M.equipped).some(([k,v])=>!['avatar','icon','token'].includes(k)||!M.cosmetics.includes(v)||v.split(':')[0]!==k))return false;
  for(const e of [M.pending,M.followup])if(e!==null){
    if(!e||typeof e.id!=='string'||!MONO_EVENTS.includes(e.type)||!MONOPOLY_RULES.multipliers.includes(e.m)||!Number.isFinite(e.base)||e.base<10||!monoSafe(e.created)||!monoSafe(e.step)||!unique(e.selected,n=>pInt(n,0,e.type==='rain'?19:['bank','megaBank'].includes(e.type)?11:8)))return false;
    if(['bank','megaBank','harvest'].includes(e.type)&&(!Array.isArray(e.deck)||e.deck.length!==(e.type==='harvest'?9:12)||!e.deck.every(n=>pInt(n,e.type==='harvest'?1:0,e.type==='harvest'?3:2))))return false;
    if(e.type==='wheel'&&(!Array.isArray(e.outcomes)||!e.outcomes.length||e.outcomes.length>2||!e.outcomes.every(n=>pInt(n,0,7))||e.step>=e.outcomes.length))return false;
    if(e.type==='chance'&&!pInt(e.outcome,0,6))return false;
    if(e.type==='rain'&&!monoSafe(e.until))return false;
  }
  return ['park','moves'].every(k=>monoSafe(M[k]))&&['rolls','events','builds'].every(k=>monoSafe(M.totals[k]));
}
function monoClock(M,now) {
  now=Math.max(M.at,Math.floor(now));
  if(M.rolls>=MONOPOLY_RULES.freeCap)M.regen=0;
  else if(M.regen&&now>=M.regen){const n=Math.min(10-M.rolls,1+Math.floor((now-M.regen)/MONOPOLY_RULES.regenMs));M.rolls+=n;M.regen=M.rolls>=10?0:M.regen+n*MONOPOLY_RULES.regenMs;}
  if(M.rolls<10&&!M.regen)M.regen=now+MONOPOLY_RULES.regenMs;
  M.at=now;
  const day=Math.floor(now/MONOPOLY_RULES.dailyMs),cycle=Math.floor(now/MONOPOLY_RULES.cycleMs);
  if(M.day.id!==day)M.day={id:day,rolls:0,events:0,builds:0,income:0,cells:0,base:monoAverage(M),points:0,taken:[]};
  if(M.cycle.id!==cycle)M.cycle={id:cycle,points:0,rolls:0,events:0,builds:0,taken:[]};
}
function monoView(S,now) { const M=S.monopoly?monoMigrate(ecoClone(S.monopoly)):monoFresh(now);if(!monoCheck(M))return null;monoClock(M,now);return M; }
function monoPrice(M) {
  const k=Object.values(M.statues).filter(n=>n===10).length*10+(M.active?M.statues[M.active]||0:0),B=MONOPOLY_RULES;
  return Math.ceil(B.statueBase*dpow(1+k/B.statueScale,B.statuePower));
}
function monoBonusS(S,id) { const M=S&&S.monopoly;return M?MONOPOLY_RULES.godBonus*(Number(M.statues&&M.statues[id]===10)+Number(M.collections&&M.collections[id]===1)):0; }
function monoBonusPackS(S) { const out={};for(const id of ALL_HERO_IDS){const b=monoBonusS(S,id);if(b)out[id]=b;}return Object.keys(out).length?out:null; }
function monoCosmeticsSync(S,M){if(M.cosmetics.includes('icon:monopoly-dollar')){const c=cosSt(S);c.b.monopoly=1;}}
function monoAverage(M) { return M.tiles.reduce((s,n)=>s+MONOPOLY_RULES.income[monoQuality(n)],0)/40; }
function monoRemaining(M) { return ALL_HERO_IDS.length*MONOPOLY_RULES.statueStages-Object.values(M.statues).reduce((a,n)=>a+n,0); }
function monoActive(M,key,now) {
  const B=MONOPOLY_RULES,slot=Math.floor(now/B.eventPeriod),scheduled=B.boostOrder[slot%B.boostOrder.length];
  return (M.boosts[key]||0)>now||(scheduled===key&&now%B.eventPeriod<B.boostDuration);
}
function monoLuckyTarget(now) {const n=Math.floor(now/MONOPOLY_RULES.eventPeriod);return [n%6+1,Math.floor(n/6)%6+1];}
function monoRolls(M,n) { M.rolls=monoAdd(M.rolls,n);if(M.rolls>=10)M.regen=0; }
function monoItem(M,index,R) {
  const id=ALL_HERO_IDS[Math.floor(index/20)],i=index%20;if(!id||!pInt(i,0,19))throw Error('Неверное действие');
  const row=M.items[id]||(M.items[id]=Array(20).fill(0)),duplicate=!!row[i];R.items.push({id,i,duplicate});
  if(duplicate)return;row[i]=1;
  if(!M.collections[id]&&row.every(Boolean)){M.collections[id]=1;monoRolls(M,100);R.completed.push({id,kind:'collection',rolls:100});}
}
function monoGrant(M,spec,r,R,base,m=1) {
  const B=MONOPOLY_RULES;
    if(spec.dollars){const n=Math.max(0,Math.floor(spec.dollars*base*m));M.dollars=monoAdd(M.dollars,n);M.day.income=monoAdd(M.day.income,n);R.dollars=monoAdd(R.dollars||0,n);}
  if(spec.rolls){const n=Math.max(0,Math.floor(spec.rolls*m));monoRolls(M,n);R.rolls=monoAdd(R.rolls||0,n);}
  // Reward cards are per source count; a multiplier creates M independent opportunities.
  for(let i=0;i<(spec.items||0)*m;i++)monoItem(M,Math.floor(r()*ALL_HERO_IDS.length*20),R);
  if(spec.boost){M.boosts[spec.boost]=Math.max(M.at,M.boosts[spec.boost]||0)+B.boostDuration;R.boost=spec.boost;}
  if(spec.chest){R.chest=spec.chest;monoGrant(M,B.chest[spec.chest-1],r,R,base,m);}
  if(spec.cosmetic){const pool=['avatar:monopoly-laurel','icon:monopoly-dollar','token:monopoly-obelisk'];const id=pool[Math.floor(r()*pool.length)];if(!M.cosmetics.includes(id)){M.cosmetics.push(id);(R.cosmetics||(R.cosmetics=[])).push(id);}}
}
function monoPoints(M,n) { M.day.points=monoAdd(M.day.points,n);M.cycle.points=monoAdd(M.cycle.points,n); }
function monoEvent(M,type,m,base,r) {
  const B=MONOPOLY_RULES,e={id:'me:'+M.moves+':'+type,type,m,base,step:0,selected:[],created:M.at};
  if(type==='bank'||type==='megaBank'){e.deck=[...B.heistDeck];for(let i=e.deck.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[e.deck[i],e.deck[j]]=[e.deck[j],e.deck[i]];}}
  if(type==='wheel')e.outcomes=[Math.floor(r()*B.wheel.length)];
  if(type==='chance')e.outcome=Math.floor(r()*B.chance.length);
  if(type==='harvest')e.deck=Array.from({length:B.harvestCards},()=>1+Math.floor(r()*3));
  if(type==='rain')e.until=0;
  M.pending=e;return e;
}
function monoLandEvent(M,m,base,r) {
  const B=MONOPOLY_RULES,p=M.pos;
  if(B.heistCells.includes(p))return monoEvent(M,monoActive(M,'megaHeist',M.at)||r()<B.megaChance?'megaBank':'bank',m,base,r);
  if(B.chanceCells.includes(p))return monoEvent(M,'chance',m,base,r);
  if(B.chestCells.includes(p))return monoEvent(M,'chest',m,base,r);
  if(B.parkingCells.includes(p))return monoEvent(M,'parking',m,base,r);
  if(B.harvestCells.includes(p))return monoEvent(M,'harvest',m,base,r);
  if(B.wheelCells.includes(p))return monoEvent(M,'wheel',m,base,r);
  if(r()<B.rainChance)return monoEvent(M,'rain',m,base,r);
  return null;
}
function monoResolve(M,p,r,R) {
  const e=M.pending,B=MONOPOLY_RULES;if(!e||p.event!==e.id)return {err:'Действие недоступно'};
  let done=false,spec=null;
  switch(e.type){
    case 'bank':case 'megaBank':{
      if(!pInt(p.pick,0,11)||e.selected.includes(p.pick))return {err:'Неверное действие'};
      e.selected.push(p.pick);const symbol=e.deck[p.pick];R.reveal={pick:p.pick,symbol};
      if(e.selected.filter(i=>e.deck[i]===symbol).length===3){spec={dollars:(e.type==='megaBank'?B.megaHeistRates:B.heistRates)[symbol]};done=true;monoPoints(M,(e.type==='megaBank'?B.tournamentMega:B.tournamentHeist)*e.m);}break;
    }
    case 'chance':spec=B.chance[e.outcome];if(monoActive(M,'luckyChance',M.at))spec={...spec,...(spec.dollars?{dollars:spec.dollars*2}:{})};R.outcome=e.outcome;done=true;break;
    case 'chest':spec={chest:1+Math.floor(r()*3)};done=true;break;
    case 'parking':{const n=M.park;M.park=0;M.dollars=monoAdd(M.dollars,n);M.day.income=monoAdd(M.day.income,n);R.dollars=n;done=true;break;}
    case 'wheel':{const outcome=e.outcomes[e.step++];spec=B.wheel[outcome];R.outcome=outcome;done=e.step>=e.outcomes.length;monoPoints(M,B.tournamentWheel*e.m);break;}
    case 'harvest':{
      if(!pInt(p.pick,0,B.harvestCards-1)||e.selected.includes(p.pick))return {err:'Неверное действие'};
      e.selected.push(p.pick);R.reveal={pick:p.pick,symbol:e.deck[p.pick]};spec={dollars:e.deck[p.pick]*B.harvestRate};done=e.selected.length>=B.harvestPicks;break;
    }
    case 'rain':{
      if(p.start===true){if(e.until)return {err:'Действие недоступно'};e.until=M.at+B.rainMs;break;}
      if(!e.until)return {err:'Действие недоступно'};
      if(p.finish===true||M.at>=e.until){done=true;break;}
      if(!pInt(p.pick,0,B.rainDrops-1)||e.selected.includes(p.pick))return {err:'Неверное действие'};
      e.selected.push(p.pick);spec={dollars:B.rainEach};done=e.selected.length===B.rainDrops;break;
    }
    default:return {err:'Неизвестное действие'};
  }
  if(spec)monoGrant(M,spec,r,R,e.base,e.m);
  R.eventType=e.type;R.eventDone=done;
  if(done){M.pending=M.followup;M.followup=null;M.totals.events++;M.day.events++;M.cycle.events++;if(M.pending)R.nextEvent=ecoClone(M.pending);}else R.event=ecoClone(e);
  return R;
}
