function tutStep(b,dt,ev) {
  if(b.v8&&b.drainSec){tutDrainStep(b,dt,ev);return;}
  if(['help1','help2'].includes(b.tutorial)&&b.phase==='fight'){tutAmbientStep(b,dt,ev);return;}
  const stage=b.tutorial, seconds=TUT_SECONDS[stage]; if(!seconds||b.phase!=='fight')return;
  b.t=Math.min(seconds,b.t+dt);
  const tick=Math.floor(b.t*2);
  if(tick===b.tick)return; b.tick=tick;
  if(stage==='trial'){tutTrialStep(b,ev);return;}
  if(b.tutCast){ev.push(b.tutCast);b.tutCast=null;}
  if(stage==='finale' && !b.arrived && b.t>=.5) {b.arrived=true;ev.push({type:'hxIn',team:'h',side:'h',id:TUT.higher,card:{id:TUT.higher,q:1,stars:1},wait:0});}
  if(stage==='finale' && !b.struck && b.t>=1.5) {b.struck=true;ev.push({type:'hxFx',team:'h',side:'h',id:TUT.higher,targets:b.enemies.slice(),allies:[],none:false});for(const u of b.enemies){u.hp=0;u.alive=false;ev.push({type:'hit',u,dmg:1000,src:'hgod'},{type:'death',u});}}
  const alive=b.enemies.filter(u=>u.alive), hs=b.heroes;
  if(alive.length && hs.length && !(stage==='finale'&&b.arrived)) {
    const u=hs[tick%hs.length], target=alive[tick%alive.length];
    if(tick>0 && tick%5===0){
      const caster=tick%10!==0?hs[Math.floor(tick/5)%hs.length]:alive[Math.floor(tick/5)%alive.length], targets=caster.side==='h'?alive:hs, hyper=tick%20===0||tick%20===15;
      ev.push({type:hyper?'hyper':'super',u:caster,targets,tgt:targets[0],dur:.9,kind:hyper?'chain':'aoe'});
      b.tutCast={type:hyper?'hyperHit':'superHit',u:caster,targets,kind:hyper?'chain':'aoe'};
    }else ev.push(tutAttack(u,target,.45));
    let hp;
    if(stage==='solo')hp=1000-100*b.t/seconds;
    else if(stage==='trio')hp=900-400*b.t/seconds;
    else if(stage==='squad')hp=(b.v7||target.hid===(b.tc||TUT).boss?500:1000)*(1-b.t/seconds);
    else hp=1000;
    const dmg=Math.max(1,Math.round(target.hp-hp));target.hp=Math.max(1,Math.round(hp));
    ev.push({type:'hit',u:target,dmg,by:u,src:tutHitSrc(u)});
    if(tick%3===0){const h=hs[(tick+1)%hs.length];h.hp=Math.max(h.maxHp*.35,h.hp-h.maxHp*.05);ev.push(tutAttack(target,h,.45),{type:'hit',u:h,dmg:Math.round(h.maxHp*.05),by:target,src:tutHitSrc(target)});}
  }
  if(b.t>=seconds){b.phase='end';if(stage==='squad')for(const u of b.enemies){u.hp=0;u.alive=false;ev.push({type:'death',u});}}
}

