const fishQ = G => Math.floor((G - 1) / 5) + 1;                                                        // качество ступени 1…100
const fishSt = G => (G - 1) % 5 + 1;                                                                   // звёзды ступени
const fishLv = G => (Math.max(1, Math.min(100, G)) - 1) / 99;                                          // эффект ступени 0…1
const fishGearCost = G => Math.round(FISH_RULES.gearKg[G - 1] * 1000);                                 // шаг G → G+1, граммы
