/* множитель кг улова: 1 + удочка + катушка + наживка + лодка (всё снаряжение XX★5 — ×5) */
const fishKgX = F => 1 + fishGearB(F.g[0]) + fishGearB(F.g[1]) + fishGearB(F.g[2]) + fishBoatB(F.g[3]);
const fishBoatX = F => 1 + fishBoatB(F.g[3]);
/* шансы качеств воды w (проценты, индекс 0 = качество I) — по правилу алтаря (167b п.10); снаряжение не влияет */
function fishOdds(w) { return FISH_RULES.odds[w - 1].slice(); }
